#[derive(Debug)]
pub(crate) struct Scope<'src: 'run, 'run> {
  bindings: Table<'src, Binding<'src, String>>,
  parent: Option<&'run Self>,
}

impl<'src, 'run> Scope<'src, 'run> {
  pub(crate) fn child(&'run self) -> Self {
    Self {
      parent: Some(self),
      bindings: Table::new(),
    }
  }

  pub(crate) fn root() -> Self {
    let mut root = Self {
      parent: None,
      bindings: Table::new(),
    };

    for (i, (key, value)) in constants().iter().enumerate() {
      root.bind(Binding {
        eager: false,
        export: false,
        file_depth: 0,
        name: Name {
          token: Token {
            column: 0,
            kind: TokenKind::Identifier,
            length: key.len(),
            line: 0,
            offset: 0,
            path: Path::new("PRELUDE"),
            src: key,
          },
        },
        number: Numerator::constant(i),
        prelude: true,
        private: false,
        value: (*value).into(),
      });
    }

    root
  }

  pub(crate) fn bind(&mut self, binding: Binding<'src>) {
    self.bindings.insert(binding);
  }

  pub(crate) fn bound(&self, name: &str) -> bool {
    self.bindings.contains_key(name)
  }

  pub(crate) fn value(&self, name: &str) -> Option<&str> {
    if let Some(binding) = self.bindings.get(name) {
      Some(binding.value.as_ref())
    } else {
      self.parent?.value(name)
    }
  }

  pub(crate) fn bindings(&self) -> impl Iterator<Item = &Binding<String>> {
    self.bindings.values()
  }

  pub(crate) fn names(&self) -> impl Iterator<Item = &str> {
    self.bindings.keys().copied()
  }

  pub(crate) fn parent(&self) -> Option<&'run Self> {
    self.parent
  }
}

  pub(crate) fn evaluation_target<'a>(
    &'a self,
    path: &'a Modulepath,
  ) -> RunResult<'src, (&'a Justfile<'a>, Option<&'a str>, HashSet<Number>)> {
    let mut current = self;

    let mut variable = None;

    for (i, component) in path.components.iter().enumerate() {
      let last = i + 1 == path.components.len();

      if last && current.assignments.contains_key(component) {
        variable = Some(component.as_ref());
        break;
      }

      if let Some(module) = current.modules.get(component) {
        current = module;
      } else if last {
        return Err(Error::EvalUnknownSubmoduleOrVariable {
          suggestion: current.suggest_variable_or_submodule(component),
          component: component.into(),
        });
      } else {
        return Err(Error::EvalUnknownSubmodule {
          suggestion: current.suggest_submodule(component),
          component: component.into(),
        });
      }
    }

    let variable_references = if let Some(variable) = variable {
      HashSet::from([current.assignments.get(variable).unwrap().number])
    } else {
      current
        .assignments
        .values()
        .filter(|assignment| !assignment.private)
        .map(|assignment| assignment.number)
        .collect()
    };

    Ok((current, variable, variable_references))
  }

  pub(crate) fn check_unstable(&self, config: &Config) -> RunResult<'src> {
    if let Some(&unstable_feature) = self.unstable_features.iter().next() {
      config.require_unstable(self, unstable_feature)?;
    }

    for module in self.modules.values() {
      module.check_unstable(config)?;
    }

    Ok(())
  }

  pub(crate) fn get_alias(&self, name: &str) -> Option<&Alias<'src>> {
    self.aliases.get(name)
  }

  pub(crate) fn get_recipe(&self, name: &str) -> Option<&Recipe<'src>> {
    self
      .recipes
      .get(name)
      .map(Arc::as_ref)
      .or_else(|| self.aliases.get(name).map(|alias| alias.target.as_ref()))
  }

  pub(crate) fn is_submodule(&self) -> bool {
    self.name.is_some()
  }

  pub(crate) fn name(&self) -> &'src str {
    self.name.map(|name| name.lexeme()).unwrap_or_default()
  }

